commands.command:
/bin/zsh -lc git rev-parse HEAD; git diff --check; git diff --stat; git diff -- slugify/slugify.py; git status --short; python - <<'PY'
import importlib
import itertools

truncate = importlib.import_module('slugify.slugify')._modern_truncate
checked = 0
for size in range(7):
    for chars in itertools.product('ax-', repeat=size):
        text = ''.join(chars)
        for separator in ('-', '::', '', 'x', 'xy'):
            mapped = text.replace('-', separator)
            for limit in range(-1, len(mapped) + 2):
                if limit <= 0 or len(mapped) <= limit:
                    expected = mapped
                else:
                    prefix = ''
                    expected = ''
                    for char in text:
                        prefix += separator if char == '-' else char
                        if len(prefix) > limit:
                            break
                        if char != '-':
                            expected = prefix
                actual = truncate(text, limit, False, separator, False)
                assert actual == expected, (text, separator, limit, actual, expected)
                checked += 1
print(f'Independent character-prefix comparison: {checked} cases passed')
PY

