from humanize import natural_list

for make_iterable in (list, tuple, iter, lambda xs: (x for x in xs), lambda xs: dict.fromkeys(xs).keys()):
    for values, expected in (([], ""), ([1], "1"), ([1, 2], "1 and 2"), ([1, 2, 3], "1, 2 and 3")):
        assert natural_list(make_iterable(values)) == expected

class SinglePass:
    def __init__(self):
        self.started = False

    def __iter__(self):
        assert not self.started
        self.started = True
        return iter([1, "two", 3])

assert natural_list(SinglePass()) == "1, two and 3"
print("Iterable boundary checks passed (21 cases)")
PY

